/**
 * Copyright notices. The LICENSE files that ship (the root one goes into the CLI package, the
 * extension's into the .vsix) name MariaDB plc. below the upstream copyright holders. So does the
 * header of every source file this run changed: Apache-2.0 §4(b) asks modified files to say so,
 * and the upstream copyright lines stay. Files the fork wrote (added by a patch or generated by a
 * rule) carry our notice alone. Runs last, on the files differing from HEAD (the upstream commit
 * plus the fork commits) and the untracked ones, so it sees what every other rule did; on an
 * already committed branding it has nothing to do.
 */
import { execFileSync } from 'node:child_process';
import path from 'node:path';
import { count, patch, read, renamedFiles, root, write } from './lib.mjs';

const NOTICE = 'Copyright (c) 2026, MariaDB plc.';

/** Sources whose header is a comment block; JSON, Markdown and assets have none. */
const HEADER_EXTENSIONS = new Set([
  '.ts',
  '.tsx',
  '.js',
  '.mjs',
  '.cjs',
  '.css',
]);

const HEADER = [
  '/**',
  ' * @license',
  ` * ${NOTICE}`,
  ' * SPDX-License-Identifier: Apache-2.0',
  ' */',
  '',
];

/** Fork files (mariadb/, .claude/) carry their own headers and are never rewritten. */
const FORK_DIRS = /^(mariadb|\.claude)\//;

/** The files this run changed and the ones it added, from `git status`. */
function changedFiles() {
  const entries = execFileSync(
    'git',
    ['status', '--porcelain=v1', '-z', '--untracked-files=all'],
    { cwd: root, encoding: 'utf8', maxBuffer: 256 * 1024 * 1024 },
  ).split('\0');
  // Files rename() moved show up as new, but they are upstream's.
  const moved = renamedFiles();
  const modified = [];
  const added = [];
  for (let i = 0; i < entries.length; i++) {
    const status = entries[i].slice(0, 2);
    const file = entries[i].slice(3);
    // A staged rename or copy is followed by its source path.
    if (/[RC]/.test(status)) i++;
    if (!file || status.includes('D') || FORK_DIRS.test(file)) continue;
    if (!HEADER_EXTENSIONS.has(path.extname(file))) continue;
    const isNew = status === '??' || status[0] === 'A';
    (isNew && !moved.has(file) ? added : modified).push(file);
  }
  return { modified, added };
}

/**
 * [first, last] lines of the comment blocks before the first line of code (after a shebang);
 * pragmas such as `/* eslint-disable *\/` may come before the license block.
 */
function leadingComments(lines) {
  const blocks = [];
  let i = lines[0]?.startsWith('#!') ? 1 : 0;
  for (; i < lines.length; i++) {
    if (/^\s*$/.test(lines[i])) continue;
    if (/^\/\*/.test(lines[i])) {
      const end = lines.findIndex((l, j) => j >= i && l.includes('*/'));
      if (end < 0) break;
      blocks.push([i, end]);
      i = end;
    } else if (/^\/\//.test(lines[i])) {
      let end = i;
      while (/^\/\//.test(lines[end + 1] ?? '')) end++;
      blocks.push([i, end]);
      i = end;
    } else break;
  }
  return blocks;
}

/**
 * Indexes of the copyright lines in the first leading comment block that has one, leaving out
 * one-line comments (`/* … *\/`) our notice can't sit beside.
 */
function copyrightLines(lines) {
  for (const [first, last] of leadingComments(lines)) {
    const found = [];
    for (let i = first; i <= last; i++)
      if (/\bCopyright\b/.test(lines[i]) && !/\/\*|\*\//.test(lines[i]))
        found.push(i);
    if (found.length) return found;
  }
  return [];
}

/** The copyright line's comment prefix (` * `, `// `) followed by our notice. */
function noticeLike(line) {
  return line.match(/^(.*?)(?:@license\s+)?Copyright\b/)[1] + NOTICE;
}

/** Upstream file: our notice below its copyright lines. Files without one are left alone. */
function addNotice(file) {
  const lines = read(file).split('\n');
  const at = copyrightLines(lines);
  if (!at.length || at.some((i) => lines[i].includes(NOTICE))) return false;
  const last = at[at.length - 1];
  lines.splice(last + 1, 0, noticeLike(lines[last]));
  write(file, lines.join('\n'));
  return true;
}

/** File the fork wrote: our notice replaces any others, or a header is added. */
function ownNotice(file) {
  const lines = read(file).split('\n');
  const at = copyrightLines(lines);
  if (at.length) {
    lines[at[0]] = noticeLike(lines[at[0]]);
    for (const i of at.slice(1).reverse()) lines.splice(i, 1);
  } else {
    lines.splice(lines[0]?.startsWith('#!') ? 1 : 0, 0, ...HEADER);
  }
  const text = lines.join('\n');
  if (text === read(file)) return false;
  write(file, text);
  return true;
}

export function apply() {
  // Below the last copyright line of the license's appendix.
  for (const file of ['LICENSE', 'packages/vscode-ide-companion/LICENSE'])
    patch(
      'copyright',
      file,
      /^( *)Copyright \d{4} .*\n(?! *Copyright \d)/m,
      `$&$1${NOTICE}\n`,
      (s) => s.includes(NOTICE),
    );

  const { modified, added } = changedFiles();
  count('copyright', modified.filter(addNotice).length);
  count('copyright', added.filter(ownNotice).length);
}
